using System.Globalization;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using AxonHub.Api.Models;
using AxonHub.Llm.Http;

namespace AxonHub.Api.Orchestration;

/// <summary>
/// The data map <c>matchesAssociationWhen</c> builds before evaluating an
/// association <c>When</c> condition (candidates_condition.go:177-188).
/// </summary>
/// <remarks>
/// The reference evaluates an expr-lang expression generated by
/// <c>objects.ToExpr</c>. The port keeps the same two-phase behaviour: first a
/// full build pass that mirrors <c>ToExpr</c> (a build error anywhere makes the
/// whole condition false, even when a sibling would short-circuit), then an
/// evaluation pass whose runtime type errors abort the whole condition exactly
/// like <c>expr.Run</c>.
/// </remarks>
public sealed record AssociationConditionData(
    long PromptTokens,
    bool Stream,
    string RequestFormat,
    string ReasoningEffort,
    bool HasImage,
    bool HasVideo,
    bool HasDocument,
    bool HasAudio,
    IReadOnlyDictionary<string, string> RequestHeaders,
    DateTimeOffset Now);

/// <summary>
/// Port of <c>objects.Evaluate</c>/<c>objects.ToExpr</c>
/// (internal/objects/condition.go:90-292) for the model-association
/// <c>When</c> conditions.
/// </summary>
/// <remarks>
/// The reference compiles the generated expression with expr-lang and runs it
/// against the data map. The expression shapes are fixed by <c>ToExpr</c>, so
/// the port evaluates the condition tree directly while reproducing the
/// runtime semantics expr gives those shapes:
/// <list type="bullet">
/// <item><c>==</c>/<c>!=</c> between unrelated types compare false/true
/// instead of failing (expr's <c>equal</c>);</item>
/// <item>ordered comparisons, <c>contains</c>, <c>startsWith</c> and
/// <c>endsWith</c> between mismatched types are runtime errors, which make the
/// whole condition false;</item>
/// <item>a missing <c>request_header</c> key indexes as the empty string
/// (Go's zero value for <c>map[string]string</c>);</item>
/// <item>an unknown field resolves to the nil value of the data map, so
/// equality is false and only <c>ne</c> is true;</item>
/// <item><c>dailyTimeWithin</c> returns false (not an error) for a non-string
/// argument or an invalid range.</item>
/// </list>
/// Field names that are not valid expr identifiers (or that collide with an
/// expr keyword) fail expression compilation in the reference, which
/// <see cref="Evaluate"/> also reports as false.
/// </remarks>
public static class AssociationConditionEvaluator
{
    private const string DailyTimeField = ModelAssociationConditionField.DailyTime;

    /// <summary>Port of <c>objects.Evaluate</c>: never throws.</summary>
    public static bool Evaluate(FilterCondition? condition, AssociationConditionData data)
    {
        ArgumentNullException.ThrowIfNull(data);

        if (condition is null)
        {
            return false;
        }

        // ToExpr runs before expr.Compile/Run: every build error makes the whole
        // condition false regardless of short-circuiting.
        if (!ValidateExpression(condition))
        {
            return false;
        }

        try
        {
            return EvaluateExpression(condition, data);
        }
        catch (ConditionRuntimeException)
        {
            // expr.Run reports a runtime error instead of aborting; Evaluate
            // then returns false for the entire condition.
            return false;
        }
    }

    /// <summary>Port of <c>ToExpr</c> validation (condition.go:111-138).</summary>
    private static bool ValidateExpression(FilterCondition condition)
    {
        var nodeType = condition.Type.Length == 0
            ? FilterCondition.TypeGroup
            : condition.Type;

        if (nodeType == FilterCondition.TypeCondition)
        {
            return ValidateLeaf(condition);
        }

        if (condition.Conditions is not { Count: > 0 } children)
        {
            // len(condition.Conditions) == 0 renders the literal "true".
            return true;
        }

        foreach (var child in children)
        {
            if (!ValidateNode(child))
            {
                return false;
            }
        }

        // normalizeLogic never fails: anything that is not "OR" is "&&".
        return true;
    }

    /// <summary>Port of <c>nodeToExpr</c> (condition.go:149-158).</summary>
    private static bool ValidateNode(FilterCondition? condition)
    {
        // Go's []Condition holds values, so a JSON null child decodes into the
        // zero Condition; conditionToExpr then fails on the empty field.
        condition ??= new FilterCondition();

        return condition.Type switch
        {
            "" or FilterCondition.TypeCondition => ValidateLeaf(condition),
            FilterCondition.TypeGroup => ValidateExpression(condition),
            _ => false,
        };
    }

    /// <summary>Port of <c>conditionToExpr</c> (condition.go:160-197).</summary>
    private static bool ValidateLeaf(FilterCondition condition)
    {
        var field = condition.Field.Trim();
        if (field.Length == 0)
        {
            return false;
        }

        if (field == DailyTimeField)
        {
            if (!TryGetLiteral(condition.Value, out _))
            {
                return false;
            }

            return condition.Operator.Trim().ToLowerInvariant() is "within" or "not_within";
        }

        if (field.StartsWith(
                ModelAssociationConditionField.RequestHeaderPrefix,
                StringComparison.Ordinal))
        {
            var headerName = field[ModelAssociationConditionField.RequestHeaderPrefix.Length..]
                .Trim();
            if (headerName.Length == 0)
            {
                return false;
            }

            if (!TryGetLiteral(condition.Value, out _))
            {
                return false;
            }

            return condition.Operator.Trim().ToLowerInvariant() is
                "eq" or "=" or "=="
                or "ne" or "!=" or "<>"
                or "contains" or "not_contains"
                or "start_with" or "end_with";
        }

        if (NormalizeOperator(condition.Operator) is null)
        {
            return false;
        }

        if (!TryGetLiteral(condition.Value, out _))
        {
            return false;
        }

        // The generated expression is "<field> <op> <literal>"; a field that is
        // not a single expr identifier (or is a keyword) fails to compile.
        return IsValidExprIdentifier(field);
    }

    /// <summary>Port of <c>normalizeOperator</c> (condition.go:199-216).</summary>
    private static string? NormalizeOperator(string operatorText) =>
        operatorText.Trim().ToLowerInvariant() switch
        {
            "lt" or "<" => "<",
            "lte" or "<=" => "<=",
            "gt" or ">" => ">",
            "gte" or ">=" => ">=",
            "eq" or "=" or "==" => "==",
            "ne" or "!=" or "<>" => "!=",
            _ => null,
        };

    /// <summary>Go/expr identifier syntax; keywords break compilation.</summary>
    private static bool IsValidExprIdentifier(string field)
    {
        if (field.Length == 0)
        {
            return false;
        }

        var first = field[0];
        if (!char.IsLetter(first) && first != '_')
        {
            return false;
        }

        for (var index = 1; index < field.Length; index++)
        {
            var c = field[index];
            if (!char.IsLetterOrDigit(c) && c != '_')
            {
                return false;
            }
        }

        return field is not ("true" or "false" or "nil")
            and not ("not" or "and" or "or" or "in" or "let")
            and not ("matches" or "contains" or "startsWith" or "endsWith");
    }

    /// <summary>Port of the evaluation half of <c>Evaluate</c> (condition.go:101-108).</summary>
    private static bool EvaluateExpression(
        FilterCondition condition,
        AssociationConditionData data)
    {
        var nodeType = condition.Type.Length == 0
            ? FilterCondition.TypeGroup
            : condition.Type;

        if (nodeType == FilterCondition.TypeCondition)
        {
            return EvaluateLeaf(condition, data);
        }

        if (condition.Conditions is not { Count: > 0 } children)
        {
            return true;
        }

        // expr's && and || short-circuit; an error in an evaluated operand still
        // aborts the whole program, which the exception models here.
        if (NormalizeLogic(condition.Logic) == "||")
        {
            foreach (var child in children)
            {
                if (EvaluateNode(child, data))
                {
                    return true;
                }
            }

            return false;
        }

        foreach (var child in children)
        {
            if (!EvaluateNode(child, data))
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>Port of <c>nodeToExpr</c> evaluation (condition.go:149-158).</summary>
    private static bool EvaluateNode(FilterCondition? condition, AssociationConditionData data)
    {
        // Validation already rejected nil children; the zero condition keeps
        // the helper total without changing any reachable result.
        condition ??= new FilterCondition();

        return condition.Type switch
        {
            "" or FilterCondition.TypeCondition => EvaluateLeaf(condition, data),
            FilterCondition.TypeGroup => EvaluateExpression(condition, data),
            _ => false,
        };
    }

    /// <summary>Port of <c>normalizeLogic</c> (condition.go:140-147).</summary>
    private static string NormalizeLogic(string logic)
        => string.Equals(logic.Trim(), "OR", StringComparison.OrdinalIgnoreCase) ? "||" : "&&";

    private static bool EvaluateLeaf(FilterCondition condition, AssociationConditionData data)
    {
        var field = condition.Field.Trim();

        if (field == DailyTimeField)
        {
            _ = TryGetLiteral(condition.Value, out var dailyLiteral);
            var within = dailyLiteral.Kind == ConditionLiteralKind.String
                && DailyTimeWithin(data.Now, dailyLiteral.StringValue);

            return string.Equals(
                    condition.Operator.Trim(),
                    "within",
                    StringComparison.OrdinalIgnoreCase)
                ? within
                : !within;
        }

        if (field.StartsWith(
                ModelAssociationConditionField.RequestHeaderPrefix,
                StringComparison.Ordinal))
        {
            return EvaluateRequestHeaderLeaf(condition, field, data);
        }

        var operand = ResolveFieldValue(field, data);

        _ = TryGetLiteral(condition.Value, out var literal);
        ValidateLiteralKind(literal);

        return NormalizeOperator(condition.Operator) switch
        {
            "==" => ValuesEqual(operand, literal),
            "!=" => !ValuesEqual(operand, literal),
            "<" => CompareOrdered(operand, literal) < 0,
            "<=" => CompareOrdered(operand, literal) <= 0,
            ">" => CompareOrdered(operand, literal) > 0,
            ">=" => CompareOrdered(operand, literal) >= 0,
            // Validation rejected every other operator.
            _ => throw new ConditionRuntimeException(),
        };
    }

    private static bool EvaluateRequestHeaderLeaf(
        FilterCondition condition,
        string field,
        AssociationConditionData data)
    {
        var headerName = HttpClientUtils.CanonicalHeaderKey(
            field[ModelAssociationConditionField.RequestHeaderPrefix.Length..].Trim());

        // Indexing a Go map with a missing key yields the value type's zero
        // value, so an absent header reads as "".
        var value = data.RequestHeaders.TryGetValue(headerName, out var stored)
            ? stored
            : string.Empty;

        _ = TryGetLiteral(condition.Value, out var literal);

        switch (condition.Operator.Trim().ToLowerInvariant())
        {
            case "eq":
            case "=":
            case "==":
                return literal.Kind == ConditionLiteralKind.String
                    && string.Equals(value, literal.StringValue, StringComparison.Ordinal);
            case "ne":
            case "!=":
            case "<>":
                return literal.Kind != ConditionLiteralKind.String
                    || !string.Equals(value, literal.StringValue, StringComparison.Ordinal);
            case "contains":
                return value.Contains(RequireStringLiteral(literal), StringComparison.Ordinal);
            case "not_contains":
                return !value.Contains(RequireStringLiteral(literal), StringComparison.Ordinal);
            case "start_with":
                return value.StartsWith(RequireStringLiteral(literal), StringComparison.Ordinal);
            case "end_with":
                return value.EndsWith(RequireStringLiteral(literal), StringComparison.Ordinal);
            default:
                throw new ConditionRuntimeException();
        }
    }

    private static string RequireStringLiteral(ConditionLiteral literal)
        => literal.Kind == ConditionLiteralKind.String
            ? literal.StringValue
            : throw new ConditionRuntimeException();

    /// <summary>The data map's known keys; anything else resolves to nil.</summary>
    private static ConditionOperand ResolveFieldValue(
        string field,
        AssociationConditionData data)
        => field switch
        {
            ModelAssociationConditionField.PromptTokens => ConditionOperand.OfInt(data.PromptTokens),
            ModelAssociationConditionField.Stream => ConditionOperand.OfBool(data.Stream),
            ModelAssociationConditionField.RequestFormat
                => ConditionOperand.OfString(data.RequestFormat),
            ModelAssociationConditionField.ReasoningEffort
                => ConditionOperand.OfString(data.ReasoningEffort),
            ModelAssociationConditionField.HasImage => ConditionOperand.OfBool(data.HasImage),
            ModelAssociationConditionField.HasVideo => ConditionOperand.OfBool(data.HasVideo),
            ModelAssociationConditionField.HasDocument => ConditionOperand.OfBool(data.HasDocument),
            ModelAssociationConditionField.HasAudio => ConditionOperand.OfBool(data.HasAudio),
            // map[string]string and time.Time are opaque to equality; ordered
            // comparisons against them are runtime errors in expr.
            ModelAssociationConditionField.RequestHeader => ConditionOperand.Other(),
            "now" => ConditionOperand.Other(),
            _ => ConditionOperand.Null(),
        };

    /// <summary>expr's <c>==</c> semantics for the generated operand types.</summary>
    private static bool ValuesEqual(ConditionOperand left, ConditionLiteral literal)
    {
        if (left.Kind == ConditionOperandKind.Int && literal.Kind is ConditionLiteralKind.Int)
        {
            return left.IntValue == literal.IntValue;
        }

        if (left.Kind == ConditionOperandKind.Int
            && literal.Kind == ConditionLiteralKind.Double)
        {
            return (double)left.IntValue == literal.DoubleValue;
        }

        return (left.Kind, literal.Kind) switch
        {
            (ConditionOperandKind.Bool, ConditionLiteralKind.Bool)
                => left.BoolValue == literal.BoolValue,
            (ConditionOperandKind.String, ConditionLiteralKind.String)
                => string.Equals(left.StringValue, literal.StringValue, StringComparison.Ordinal),
            _ => false,
        };
    }

    /// <summary>Ordered comparison; mismatched types are runtime errors in expr.</summary>
    private static int CompareOrdered(ConditionOperand left, ConditionLiteral literal)
    {
        if (left.Kind == ConditionOperandKind.Int && literal.Kind == ConditionLiteralKind.Int)
        {
            return left.IntValue.CompareTo(literal.IntValue);
        }

        if (left.Kind == ConditionOperandKind.Int
            && literal.Kind == ConditionLiteralKind.Double)
        {
            return ((double)left.IntValue).CompareTo(literal.DoubleValue);
        }

        if (left.Kind == ConditionOperandKind.String
            && literal.Kind == ConditionLiteralKind.String)
        {
            // Go compares strings byte-wise over their UTF-8 encoding.
            return CompareGoStrings(left.StringValue, literal.StringValue);
        }

        throw new ConditionRuntimeException();
    }

    private static int CompareGoStrings(string left, string right)
    {
        var leftBytes = Encoding.UTF8.GetBytes(left);
        var rightBytes = Encoding.UTF8.GetBytes(right);
        var length = Math.Min(leftBytes.Length, rightBytes.Length);
        for (var index = 0; index < length; index++)
        {
            var byByte = leftBytes[index].CompareTo(rightBytes[index]);
            if (byByte != 0)
            {
                return byByte;
            }
        }

        return leftBytes.Length.CompareTo(rightBytes.Length);
    }

    /// <summary>
    /// Runtime type errors for literals that expr could not use against the
    /// generated operand: nil/object/array literals never reach evaluation
    /// because <c>literalExpr</c> rejects them during the build pass.
    /// </summary>
    private static void ValidateLiteralKind(ConditionLiteral literal)
    {
        if (literal.Kind == ConditionLiteralKind.Unsupported)
        {
            throw new ConditionRuntimeException();
        }
    }

    /// <summary>Port of <c>xtime.DailyTimeWithin</c> (internal/pkg/xtime/time.go).</summary>
    private static bool DailyTimeWithin(DateTimeOffset now, string value)
    {
        if (!DailyTime.TryParseRange(value, out var start, out var end, out _))
        {
            return false;
        }

        var current = (now.Hour * 60) + now.Minute;
        var startMinutes = (start.Hours * 60) + start.Minutes;
        var endMinutes = (end.Hours * 60) + end.Minutes;

        return startMinutes <= endMinutes
            ? current >= startMinutes && current < endMinutes
            : current >= startMinutes || current < endMinutes;
    }

    /// <summary>
    /// Port of <c>literalExpr</c> (condition.go:251-292): nil and composite
    /// values are build errors; JSON numbers were normalized to int64/float64
    /// by <c>normalizeJSONNumberValue</c> during decoding.
    /// </summary>
    private static bool TryGetLiteral(JsonNode? node, out ConditionLiteral literal)
    {
        literal = default;

        if (node is not JsonValue value)
        {
            return false;
        }

        if (value.TryGetValue<JsonElement>(out var element))
        {
            switch (element.ValueKind)
            {
                case JsonValueKind.String:
                    literal = ConditionLiteral.OfString(element.GetString() ?? string.Empty);
                    return true;
                case JsonValueKind.True:
                case JsonValueKind.False:
                    literal = ConditionLiteral.OfBool(element.GetBoolean());
                    return true;
                case JsonValueKind.Number:
                    literal = ParseNumber(element.GetRawText());
                    return true;
                default:
                    return false;
            }
        }

        switch (value.GetValueKind())
        {
            case JsonValueKind.String:
                literal = ConditionLiteral.OfString(value.GetValue<string>());
                return true;
            case JsonValueKind.True:
            case JsonValueKind.False:
                literal = ConditionLiteral.OfBool(value.GetValue<bool>());
                return true;
            case JsonValueKind.Number:
                if (value.TryGetValue<long>(out var int64))
                {
                    literal = ConditionLiteral.OfInt(int64);
                    return true;
                }

                if (value.TryGetValue<int>(out var int32))
                {
                    literal = ConditionLiteral.OfInt(int32);
                    return true;
                }

                if (value.TryGetValue<double>(out var double64)
                    && double.IsFinite(double64))
                {
                    literal = ConditionLiteral.OfDouble(double64);
                    return true;
                }

                if (value.TryGetValue<float>(out var single)
                    && float.IsFinite(single))
                {
                    literal = ConditionLiteral.OfDouble(single);
                    return true;
                }

                if (value.TryGetValue<decimal>(out var decimal64))
                {
                    literal = ConditionLiteral.OfDouble((double)decimal64);
                    return true;
                }

                literal = ParseNumber(value.ToJsonString());
                return literal.Kind != ConditionLiteralKind.Unsupported;
            default:
                return false;
        }
    }

    /// <summary>Port of normalizeJSONNumberValue's json.Number branches.</summary>
    private static ConditionLiteral ParseNumber(string raw)
    {
        if (long.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out var integer))
        {
            return ConditionLiteral.OfInt(integer);
        }

        if (double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out var floating)
            && double.IsFinite(floating))
        {
            return ConditionLiteral.OfDouble(floating);
        }

        // strconv.ParseFloat failed (range error): the reference falls back to
        // the raw text as a string.
        return ConditionLiteral.OfString(raw);
    }

    private enum ConditionLiteralKind
    {
        Unsupported,
        String,
        Bool,
        Int,
        Double,
    }

    private readonly struct ConditionLiteral
    {
        public ConditionLiteralKind Kind { get; init; }

        public string StringValue { get; init; }

        public bool BoolValue { get; init; }

        public long IntValue { get; init; }

        public double DoubleValue { get; init; }

        public static ConditionLiteral OfString(string value) => new()
        {
            Kind = ConditionLiteralKind.String,
            StringValue = value,
        };

        public static ConditionLiteral OfBool(bool value) => new()
        {
            Kind = ConditionLiteralKind.Bool,
            BoolValue = value,
        };

        public static ConditionLiteral OfInt(long value) => new()
        {
            Kind = ConditionLiteralKind.Int,
            IntValue = value,
        };

        public static ConditionLiteral OfDouble(double value) => new()
        {
            Kind = ConditionLiteralKind.Double,
            DoubleValue = value,
        };
    }

    private enum ConditionOperandKind
    {
        Null,
        String,
        Bool,
        Int,
        Other,
    }

    private readonly struct ConditionOperand
    {
        public ConditionOperandKind Kind { get; init; }

        public string StringValue { get; init; }

        public bool BoolValue { get; init; }

        public long IntValue { get; init; }

        public static ConditionOperand Null() => new()
        {
            Kind = ConditionOperandKind.Null,
        };

        public static ConditionOperand Other() => new()
        {
            Kind = ConditionOperandKind.Other,
        };

        public static ConditionOperand OfString(string value) => new()
        {
            Kind = ConditionOperandKind.String,
            StringValue = value,
        };

        public static ConditionOperand OfBool(bool value) => new()
        {
            Kind = ConditionOperandKind.Bool,
            BoolValue = value,
        };

        public static ConditionOperand OfInt(long value) => new()
        {
            Kind = ConditionOperandKind.Int,
            IntValue = value,
        };
    }

    /// <summary>Stands in for an expr runtime error; aborts the whole condition.</summary>
    private sealed class ConditionRuntimeException : Exception
    {
    }
}
